printBlocks.excerpt:
/* Print the reference as a compact handout; browser print settings may still override colors. */
@page { size: letter portrait; margin: .35in; }
@media print {
  html,body { margin:0!important; padding:0!important; background:white!important; color:#142B49!important; }
  html,body,#quick-reference,#quick-reference * { -webkit-print-color-adjust:exact!important; print-color-adjust:exact!important; }
  .topbar,.rail,.mobile-nav,.bottom-controls,#nav-status,.lesson-view,.print-hide { display:none!important; }
  .dsl-layout,.dsl-layout.sidebar-collapsed { display:block!important; padding:0!important; margin:0!important; min-height:0!important; }
  .dsl-content { max-width:none!important; width:100%!important; margin:0!important; padding:0!important; }
  #view-7 { display:block!important; margin:0!important; padding:0!important; }
  #quick-reference { box-shadow:none!important; border:0!important; border-radius:0!important; margin:0!important; padding:0!important; font-size:9pt!important; line-height:1.2!important; }
  #quick-reference h2 { font-size:17pt!important; margin:0!important; }
  #quick-reference h4 { font-size:10pt!important; }
  #quick-reference p { margin-top:3px!important; margin-bottom:3px!important; }
  #quick-reference .mb-6 { margin-bottom:9px!important; }
  #quick-reference .mb-4 { margin-bottom:6px!important; }
  #quick-reference .mb-3 { margin-bottom:5px!important; }
  #quick-reference .mt-4 { margin-top:6px!important; }
  #quick-reference .gap-4 { gap:7px!important; }
  #quick-reference .gap-3 { gap:5px!important; }
  #quick-reference .gap-2 { gap:4px!important; }
  #quick-reference .p-3,#quick-reference .\!p-5 { padding:7px!important; }
  #reference-content { display:grid!important; grid-template-columns:repeat(2,minmax(0,1fr))!important; gap:7px!important; }
  #reference-content > :first-child,#reference-content > :last-child { grid-column:1/-1!important; }
  #quick-reference section,#quick-reference .card { break-inside:avoid!important; page-break-inside:avoid!important; }
  #quick-reference .sm\:grid-cols-3 { display:grid!important; grid-template-columns:repeat(6,minmax(0,1fr))!important; }
  #quick-reference .sm\:grid-cols-2 { display:grid!important; grid-template-columns:repeat(4,minmax(0,1fr))!important; }
}

/* Middle Stage print isolation: shared.css prints Opening Stage's #view-7.
   In Middle Stage #view-7 is the knowledge check, not the reference. */
@media print {
  #view-7, #view-7[hidden] { display:none!important; }
  #view-8, #view-8[hidden] { display:block!important; }
  #view-8 { break-before:auto!important; page-break-before:auto!important; }
}

/* Final print override: isolate only the Middle Stage reference page. */
@media print {
  .dsl-content > .lesson-view:not(#view-8),
  #view-7, #view-7[hidden], .view#print-view {display:none!important;}
  .dsl-content > #view-8, .dsl-content > #view-8[hidden] {display:block!important;}
  #view-8 .middle-reference-sheet {break-before:auto!important;page-break-before:auto!important;}
}

/* Print by reference role, never by another lesson's page number. */
@media print{
 .dsl-content > .lesson-view:not(#view-9),#view-7,#view-8{display:none!important}
 .dsl-content > #view-9,.dsl-content > #view-9[hidden]{display:block!important}
 #view-9 .final-reference-sheet{border:0!important;box-shadow:none!important;padding:0!important;margin:0!important}
 #view-9 .final-reference-header{gap:0!important;margin-bottom:10px!important}
 #view-9 .final-reference-header h2{font-size:17pt!important}
 #view-9 .final-reference-item{padding:9px 12px!important;margin-bottom:7px!important;break-inside:avoid!important;page-break-inside:avoid!important}
 #view-9 .final-reference-item h3{font-size:10pt!important;margin-bottom:5px!important}
 #view-9 .final-reference-item p{font-size:9pt!important;line-height:1.25!important;margin:2px 0!important}
 #view-9 .final-reference-number{height:26px!important;min-width:34px!important;font-size:9pt!important}
 html,body,#view-9,#view-9 *{-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important}
}

@media print{
 .dsl-final #views > .lesson-view:not([data-reference-view]){display:none!important}
 .dsl-final #views > [data-reference-view],.dsl-final #views > [data-reference-view][hidden]{display:block!important}
 .dsl-final #views > [data-reference-view] > h2,.dsl-final #lesson-status,.dsl-final [data-reference-retry]{display:none!important}
 /* Native print while loading/failed must explain an incomplete reference. */
 .dsl-final [data-reference-status]:not([hidden]){display:block!important}
}

@media print {
  .dsl-opening #lesson-status,.dsl-opening #lesson-retry,.dsl-opening #storage-warning,
  .dsl-opening [data-reference-print],.dsl-opening [data-reference-retry] { display:none!important; }
  .dsl-opening #view-7,.dsl-opening #view-7[hidden] { display:block!important; }
  .dsl-opening #view-7 > p:first-child { display:none!important; }
  .dsl-opening [data-reference-status]:not([hidden]) { display:block!important; }
  .dsl-opening #reference-content { gap:7px!important; }
  .dsl-opening .opening-reference-badge { padding:4px 12px!important; }
  .dsl-opening .opening-reference-group { padding:7px!important; }
  .dsl-opening .opening-reference-group h4 { margin-bottom:5px!important; }
  .dsl-opening .opening-reference-group ul { gap:4px!important; }
  .dsl-opening .opening-reference-group li { font-size:9pt!important; padding:7px!important; }
  .dsl-opening .opening-reference-1 ul { grid-template-columns:repeat(6,minmax(0,1fr))!important; }
  .dsl-opening .opening-reference-4 ul { grid-template-columns:repeat(4,minmax(0,1fr))!important; }
}
